<?php require '../config/db.php';require '../includes/functions.php';if(session_status()!==PHP_SESSION_ACTIVE)session_start();$email=trim($_POST['email']??'');$pass=$_POST['password']??'';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$pass==='')json_response(false,'Enter a valid email and password.',[],422);$q=$pdo->prepare('SELECT * FROM users WHERE email=? AND status=\'active\' LIMIT 1');$q->execute([$email]);$u=$q->fetch();if(!$u||!password_verify($pass,$u['password_hash']))json_response(false,'Email or password is incorrect.',[],401);$_SESSION['admin']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];json_response(true,'Login successful. Opening dashboard.',['redirect'=>'admin/index.php']);